import{_ as t,o as r,c as n,a3 as s}from"./chunks/framework.Crt1tuW8.js";const h=JSON.parse('{"title":"Grille d’évaluation — TP2","description":"","frontmatter":{"title":"Grille d’évaluation — TP2"},"headers":[],"relativePath":"grilles/grille-tp2.md","filePath":"grilles/grille-tp2.md"}'),a={name:"grilles/grille-tp2.md"};function o(i,e,d,l,u,c){return r(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="grille-d-evaluation-—-travail-pratique-2" tabindex="-1">Grille d’évaluation — Travail Pratique #2 <a class="header-anchor" href="#grille-d-evaluation-—-travail-pratique-2" aria-label="Permalink to &quot;Grille d’évaluation — Travail Pratique #2&quot;">​</a></h1><p>Le TP2 vaut <strong>13 %</strong> de la note finale, répartis en deux parties :</p><table tabindex="0"><thead><tr><th>Partie</th><th>Description</th><th>Poids</th></tr></thead><tbody><tr><td><strong>A</strong></td><td>Travail à la maison — insertions et 15 requêtes</td><td>6 %</td></tr><tr><td><strong>B</strong></td><td>Évaluation supervisée en classe, sur une base fournie</td><td>7 %</td></tr></tbody></table><p>Chaque critère est évalué selon des niveaux de performance. Les pondérations indiquent le poids de chaque critère dans la note de la partie concernée.</p><hr><h1 id="partie-a-—-travail-a-la-maison-6" tabindex="-1">Partie A — travail à la maison (6 %) <a class="header-anchor" href="#partie-a-—-travail-a-la-maison-6" aria-label="Permalink to &quot;Partie A — travail à la maison (6 %)&quot;">​</a></h1><h2 id="_1-insertion-des-donnees-—-20" tabindex="-1">1) Insertion des données — 20 % <a class="header-anchor" href="#_1-insertion-des-donnees-—-20" aria-label="Permalink to &quot;1) Insertion des données — 20 %&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th><th>Note</th></tr></thead><tbody><tr><td><strong>Excellent</strong></td><td>Insertions pleinement fonctionnelles. 25 à 60 lignes dans chacune des quatre tables à remplir. Contraintes respectées. Données variées, cohérentes et plausibles, permettant à toutes les requêtes de retourner des résultats significatifs.</td><td>100 %</td></tr><tr><td><strong>Suffisant</strong></td><td>Insertions fonctionnelles, mais quelques éléments mineurs à ajuster (variété, cohérence ou respect de certaines contraintes).</td><td>60 %</td></tr><tr><td><strong>Absent ou insuffisant</strong></td><td>Insertions non fonctionnelles ou plusieurs éléments importants à corriger (quantité, cohérence ou contraintes).</td><td>0 %</td></tr></tbody></table><hr><h2 id="_2-requetes-de-selection-et-sous-requetes-q1-a-q12-—-50" tabindex="-1">2) Requêtes de sélection et sous-requêtes (Q1 à Q12) — 50 %* <a class="header-anchor" href="#_2-requetes-de-selection-et-sous-requetes-q1-a-q12-—-50" aria-label="Permalink to &quot;2) Requêtes de sélection et sous-requêtes (Q1 à Q12) — 50 %*&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th><th>Note</th></tr></thead><tbody><tr><td><strong>Excellent</strong></td><td>Toutes les requêtes sont fonctionnelles et conformes aux consignes. Filtres, tris, colonnes demandées et gestion des doublons correctement appliqués.</td><td>100 %</td></tr><tr><td><strong>Suffisant</strong></td><td>Les requêtes fonctionnent globalement, mais un à quelques éléments mineurs sont à ajuster (tri, filtre, colonnes retournées, précision des résultats).</td><td>60 %</td></tr><tr><td><strong>Insuffisant</strong></td><td>Plusieurs requêtes ne fonctionnent pas ou produisent des résultats incorrects. Logique partiellement ou majoritairement erronée.</td><td>0 %</td></tr></tbody></table><blockquote><p>*Chaque requête est évaluée individuellement.</p></blockquote><hr><h2 id="_3-modifications-et-suppression-q13-a-q15-—-30" tabindex="-1">3) Modifications et suppression (Q13 à Q15) — 30 %* <a class="header-anchor" href="#_3-modifications-et-suppression-q13-a-q15-—-30" aria-label="Permalink to &quot;3) Modifications et suppression (Q13 à Q15) — 30 %*&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th><th>Note</th></tr></thead><tbody><tr><td><strong>Excellent</strong></td><td>Les mises à jour et la suppression sont correctement ciblées. Aucune ligne non prévue n’est affectée. Logique sécuritaire et conforme aux consignes.</td><td>100 %</td></tr><tr><td><strong>Suffisant</strong></td><td>Les requêtes fonctionnent mais le ciblage ou la logique présente un ou quelques éléments mineurs à corriger.</td><td>60 %</td></tr><tr><td><strong>Insuffisant</strong></td><td>Requêtes non fonctionnelles, ciblage incorrect ou logique dangereuse (impact involontaire sur plusieurs lignes).</td><td>0 %</td></tr></tbody></table><blockquote><p>*Chaque requête est évaluée individuellement.</p></blockquote><hr><div class="my-6 rounded-lg border border-red-300 bg-red-50 p-4 text-red-900"><strong>Conditions de recevabilité de la partie A</strong><br> Le fichier doit être remis au bon format (<code>tp2_prenom_nom.sql</code>), respecter l&#39;ordre et les commentaires du fichier de départ, et s&#39;exécuter <strong>du début à la fin sans erreur</strong>. Un fichier qui s&#39;interrompt à la première instruction est corrigé tel quel. </div><hr><h1 id="partie-b-—-evaluation-supervisee-7" tabindex="-1">Partie B — évaluation supervisée (7 %) <a class="header-anchor" href="#partie-b-—-evaluation-supervisee-7" aria-label="Permalink to &quot;Partie B — évaluation supervisée (7 %)&quot;">​</a></h1><p>Questions courtes sur une base fournie en classe, corrigées <strong>à la requête</strong>. Chaque question vaut le même nombre de points.</p><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th><th>Note</th></tr></thead><tbody><tr><td><strong>Excellent</strong></td><td>La requête s’exécute et retourne exactement le résultat attendu (lignes, colonnes et ordre).</td><td>100 %</td></tr><tr><td><strong>Suffisant</strong></td><td>La requête s’exécute et la logique est la bonne, mais le résultat présente un écart mineur : colonne superflue ou manquante, tri absent, doublons non éliminés, borne d’intervalle inexacte.</td><td>60 %</td></tr><tr><td><strong>Insuffisant</strong></td><td>La requête ne s’exécute pas, ou retourne un résultat qui ne correspond pas à la demande.</td><td>0 %</td></tr></tbody></table><div class="my-6 rounded-lg border border-yellow-300 bg-yellow-50 p-4 text-yellow-900"><strong>Écart entre les deux parties</strong><br> Un écart important entre la qualité de la partie A et celle de la partie B peut donner lieu à une rencontre de validation, où l&#39;étudiant est invité à expliquer le code remis en partie A. </div>',23)])])}const q=t(a,[["render",o]]);export{h as __pageData,q as default};
